// Generated from upstream sc/qa/unit/data/functions/statistical/fods/*.fods (up to 25 test
// formulas of Sheet2's first column per file, with the cells and named ranges they refer to). The
// expected results are the values LibreOffice stored, except for the stale ones listed in
// STAT_OVERRIDDEN, which LibreOffice 26.2 itself computes differently today.
export interface StatSheetCase {
  file: string;
  sheets: string[];
  /** [name, range, base address] */
  names: [string, string, string][];
  /** [sheet, column, first row, cells]: a number, a text, { f: ODFF formula }, { m: [ODFF array formula, columns, rows] } or null. */
  cells: [number, number, number, (number | string | { f: string } | { m: [string, number, number] } | null)[]][];
  /** [row in Sheet2 column A, formula, expected number or displayed text] */
  checks: [number, string, number | string][];
}

